INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch04$PT159-S1-Q4$batch04$, 159, 1, 4, $batch04$Paradox$batch04$, $batch04$A process of extracting caffeine from coffee without seriously compromising the coffee’s taste was introduced a number of years ago. When this decaffeinated coffee first came on the market, however, many coffee drinkers reported that it tasted rather bad.$batch04$, $batch04$Which one of the following, if true, most helps to resolve the apparent discrepancy in the statements above?$batch04$, $batch04$E$batch04$, true, $batch04$Batch 04; question text from local bank.$batch04$ FROM lr_sections s WHERE s.preptest=159 AND s.section=1 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch04$PT159-S1-Q4$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$A$batch04$, $batch04$The percentage of coffee drinkers who drink only decaffeinated coffee is much larger today than it was at the time the process was introduced.$batch04$, $batch04$No Impact$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT159-S1-Q4$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$A$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$B$batch04$, $batch04$Many coffee drinkers would not drink decaffeinated coffee even if they believed that it tasted as good as regular coffee.$batch04$, $batch04$No Impact$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT159-S1-Q4$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$B$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$C$batch04$, $batch04$The taste of any kind of coffee can be affected by the foods that are consumed along with it.$batch04$, $batch04$Applies to Both$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT159-S1-Q4$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$C$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$D$batch04$, $batch04$Coffee that is decaffeinated through this process generally costs more than regular coffee.$batch04$, $batch04$Out of Scope$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT159-S1-Q4$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$D$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$E$batch04$, $batch04$During the years in which the process was introduced, coffee processors used only low-quality coffee beans for their decaffeinated products.$batch04$, $batch04$Correct$batch04$, true FROM lr_questions q WHERE q.qid=$batch04$PT159-S1-Q4$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$E$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch04$PT159-S1-Q4$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch04$Given that$batch04$, $batch04$The decaffeination process does not seriously compromise coffee's taste.$batch04$), (1, $batch04$How can it be that$batch04$, $batch04$When decaf first came out, many drinkers said it tasted rather bad?$batch04$), (2, $batch04$Evaluate$batch04$, $batch04$If the process is not the problem, something else about early decaf must be. The beans used, or how it was made, could explain the bad taste.$batch04$), (3, $batch04$Goal$batch04$, $batch04$Find a cause of bad taste in early decaf other than the process.$batch04$)) v(position,label,body) WHERE q.qid=$batch04$PT159-S1-Q4$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch04$A$batch04$, $batch04$More people drinking decaf today does not explain why it tasted bad at first.$batch04$), ($batch04$B$batch04$, $batch04$Whether people would drink it does not explain how it tasted.$batch04$), ($batch04$C$batch04$, $batch04$Food affects the taste of all coffee, regular and decaf alike, so it cannot explain why decaf tasted worse.$batch04$), ($batch04$D$batch04$, $batch04$Price is not taste.$batch04$), ($batch04$E$batch04$, $batch04$Processors used only low-quality beans for early decaf. The coffee tasted bad because of the beans, not the process.$batch04$)) v(letter,body) WHERE q.qid=$batch04$PT159-S1-Q4$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
